using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(storageRootPath: "eval-results");
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static IChatClient CreateChatClient()
    {
        // Uses the chat client configured in the app host.
        // In CI, configure AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_DEPLOYMENT environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        var chatClient = CreateChatClient();
        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator()
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var context = new EvaluationContext();
        var results = await EvaluationMetric.EvaluateAsync(evaluators, messages, chatClient, context);

        foreach (var metric in results)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        var chatClient = CreateChatClient();
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator()
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in simple terms.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var context = new EvaluationContext();
        var results = await EvaluationMetric.EvaluateAsync(evaluators, messages, chatClient, context);

        foreach (var metric in results)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsFluent()
    {
        var chatClient = CreateChatClient();
        var evaluators = new IEvaluator[]
        {
            new FluencyEvaluator()
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a brief summary of the water cycle.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var context = new EvaluationContext();
        var results = await EvaluationMetric.EvaluateAsync(evaluators, messages, chatClient, context);

        foreach (var metric in results)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < EvaluationRating.Average,
                $"Metric '{metric.Name}' scored below average: {metric.Rating}");
        }
    }
}

